macro_rules! deps {
    () => {
        Config!();
        ArcSwapAny!();
    };
}

macro_rules! Cache {
    () => {
        deps!();
        # [doc = " Caching handle for [`ArcSwapAny`][ArcSwapAny]."] # [doc = ""] # [doc = " Instead of loading the [`Arc`][Arc] on every request from the shared storage, this keeps"] # [doc = " another copy inside itself. Upon request it only cheaply revalidates it is up to"] # [doc = " date. If it is, access is significantly faster. If it is stale, the [load_full] is done and the"] # [doc = " cache value is replaced. Under a read-heavy loads, the measured speedup are 10-25 times,"] # [doc = " depending on the architecture."] # [doc = ""] # [doc = " There are, however, downsides:"] # [doc = ""] # [doc = " * The handle needs to be kept around by the caller (usually, one per thread). This is fine if"] # [doc = "   there's one global `ArcSwapAny`, but starts being tricky with eg. data structures build from"] # [doc = "   them."] # [doc = " * As it keeps a copy of the [Arc] inside the cache, the old value may be kept alive for longer"] # [doc = "   period of time ‒ it is replaced by the new value on [load][Cache::load]. You may not want to"] # [doc = "   use this if dropping the old value in timely manner is important (possibly because of"] # [doc = "   releasing large amount of RAM or because of closing file handles)."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " # fn do_something<V>(_v: V) { }"] # [doc = " use std::sync::Arc;"] # [doc = " use std::sync::atomic::{AtomicBool, Ordering};"] # [doc = ""] # [doc = " use arc_swap::{ArcSwap, Cache};"] # [doc = ""] # [doc = " let shared = Arc::new(ArcSwap::from_pointee(42));"] # [doc = " # let mut threads = Vec::new();"] # [doc = " let terminate = Arc::new(AtomicBool::new(false));"] # [doc = " // Start 10 worker threads..."] # [doc = " for _ in 0..10 {"] # [doc = "     let mut cache = Cache::new(Arc::clone(&shared));"] # [doc = "     let terminate = Arc::clone(&terminate);"] # [doc = "     # let thread ="] # [doc = "     std::thread::spawn(move || {"] # [doc = "         // Keep loading it like mad.."] # [doc = "         while !terminate.load(Ordering::Relaxed) {"] # [doc = "             let value = cache.load();"] # [doc = "             do_something(value);"] # [doc = "         }"] # [doc = "     });"] # [doc = "     # threads.push(thread);"] # [doc = " }"] # [doc = " shared.store(Arc::new(12));"] # [doc = " # terminate.store(true, Ordering::Relaxed);"] # [doc = " # for thread in threads { thread.join().unwrap() }"] # [doc = " ```"] # [doc = ""] # [doc = " Another one with using a thread local storage and explicit types:"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use std::sync::Arc;"] # [doc = " # use std::ops::Deref;"] # [doc = " # use std::cell::RefCell;"] # [doc = " #"] # [doc = " # use arc_swap::ArcSwap;"] # [doc = " # use arc_swap::cache::Cache;"] # [doc = " # use once_cell::sync::Lazy;"] # [doc = " #"] # [doc = " # #[derive(Debug, Default)]"] # [doc = " # struct Config;"] # [doc = " #"] # [doc = " static CURRENT_CONFIG: Lazy<ArcSwap<Config>> = Lazy::new(|| ArcSwap::from_pointee(Config::default()));"] # [doc = ""] # [doc = " thread_local! {"] # [doc = "     static CACHE: RefCell<Cache<&'static ArcSwap<Config>, Arc<Config>>> = RefCell::new(Cache::from(CURRENT_CONFIG.deref()));"] # [doc = " }"] # [doc = ""] # [doc = " CACHE.with(|c| {"] # [doc = "     // * RefCell needed, because load on cache is `&mut`."] # [doc = "     // * You want to operate inside the `with` ‒ cloning the Arc is comparably expensive as"] # [doc = "     //   ArcSwap::load itself and whatever you'd save by the cache would be lost on that."] # [doc = "     println!(\"{:?}\", c.borrow_mut().load());"] # [doc = " });"] # [doc = " ```"] # [doc = ""] # [doc = " [Arc]: std::sync::Arc"] # [doc = " [load_full]: ArcSwapAny::load_full"] # [derive (Clone , Debug)] pub struct Cache < A , T > { arc_swap : A , cached : T , }
    };
}

Cache!();